        if b & 0x40:  # new format
            tag = b & 0x3F
            lb = data[i]; i += 1
            if lb < 192:
                length = lb
            elif lb < 224:
                length = ((lb - 192) << 8) + data[i] + 192; i += 1
            elif lb == 255:
                length = struct.unpack('>I', data[i:i+4])[0]; i += 4
            else:
                raise ValueError("partial lengths unsupported")
        else:  # old format
            tag = (b >> 2) & 0x0F
            lt = b & 0x03
            if lt == 0:
                length = data[i]; i += 1
            elif lt == 1:
